template <int N>
struct Fact {
    static constexpr int value = N * Fact<N - 1>::value;
};

template <>
struct Fact<0> {
    static constexpr int value = 1;
};

// CRTP - Compile-Time Polymorphism
template <typename D>
class Base {
public:
    // Static dispatch (no virtual table overhead)
    void execute() { static_cast<D*>(this)->specific_action(); }
};

class Policy : public Base<Policy> {
public:
    void specific_action() { /* specialized behavior */ }
};
